import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Microsoft 365 Copilot data security — enumerated source for the Data Security for Copilot for Microsoft 365 assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/m365-copilot-data-security-question-set.md","filePath":"frameworks/m365-copilot-data-security-question-set.md"}'),d={name:"frameworks/m365-copilot-data-security-question-set.md"};function i(n,t,s,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="microsoft-365-copilot-data-security-—-enumerated-source-for-the-data-security-for-copilot-for-microsoft-365-assessment" tabindex="-1">Microsoft 365 Copilot data security — enumerated source for the Data Security for Copilot for Microsoft 365 assessment <a class="header-anchor" href="#microsoft-365-copilot-data-security-—-enumerated-source-for-the-data-security-for-copilot-for-microsoft-365-assessment" aria-label="Permalink to &quot;Microsoft 365 Copilot data security — enumerated source for the Data Security for Copilot for Microsoft 365 assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>m365.copilot.datasecurity.yaml</code> is a readiness review of the data-security work that comes before and alongside a Microsoft 365 Copilot deployment: finding and fixing oversharing, labelling and protecting data, putting guardrails around Copilot, auditing its use and meeting AI regulations. It is Scout&#39;s counterpart to Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/dde5dcfc-77d3-4f71-aa3f-cc98fa893e99/" target="_blank" rel="noreferrer">Data Security for Copilot for Microsoft 365</a> assessment. <code>src/assess/rules/m365.copilot.datasecurity.yaml</code> is written against this page only, and every rule cites an item number from the tables below. Every item is a <strong>manual</strong> question answered with <code>-AssessmentAnswers</code>, because Scout does not read Microsoft 365 data.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/dde5dcfc-77d3-4f71-aa3f-cc98fa893e99/" target="_blank" rel="noreferrer">Data Security for Copilot for Microsoft 365</a> (question text not published)</td></tr><tr><td>Framework version</td><td>Microsoft 365 Copilot data security guidance on Microsoft Learn (secure-and-govern blueprint, Zero Trust for Copilot, SharePoint Advanced Management), current as of the extraction date; no published version number</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Pages marked <code>fetched</code> in the source list were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Pages marked <code>search excerpt</code> were read through <code>microsoft_docs_search</code> excerpts on the same day, not in full. The Microsoft Graph and SharePoint interfaces named in the last section were checked against Learn reference pages the same day. No Microsoft 365 tenant was read.</td></tr></tbody></table><h2 id="product-status" tabindex="-1">Product status <a class="header-anchor" href="#product-status" aria-label="Permalink to &quot;Product status&quot;">​</a></h2><p>Checked against Microsoft Learn on 2026-11-25.</p><ul><li><strong>Renamed, not retired.</strong> The assessment still carries the old name &quot;Copilot for Microsoft 365&quot;. Current Learn guidance calls the product Microsoft 365 Copilot, and the deployment blueprint and Purview DLP pages say Microsoft Copilot. The items apply to the product under its current name.</li><li><strong>A feature in the guidance is retiring.</strong> Restricted SharePoint Search is retiring: Learn states that from 2026-07-31 new enablement is blocked, and points to Restricted Content Discovery for controlling discoverability. M365CP-RO-05 asks how an existing allow list is being retired.</li><li><strong>Renamed DLP location.</strong> The Purview DLP policy location that governs Copilot is titled &quot;Microsoft Copilot, Copilot Chat, and Copilot Cowork&quot; on current pages. M365CP-GR-01 to GR-03 use it. Learn&#39;s Purview service description lists the sensitivity-label condition (keep labelled files and emails out of Copilot) as included in Microsoft 365 E5 licensing and not in E3, and prompt protection as available to all Copilot users.</li><li><strong>Current structure.</strong> Microsoft&#39;s blueprint has three pillars: remediate oversharing, set up guardrails, meet regulations. The groups below follow it, with separate groups for sensitivity labels, audit and agents.</li></ul><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>The questions are Scout-derived, not Microsoft&#39;s.</strong> The assessment&#39;s question text is not published, so the items below are Scout&#39;s reading of the guidance listed above. The <code>M365CP-*</code> IDs, and the assignment of an item to a group, are Scout&#39;s own.</p><p><strong>Scout does not read this product&#39;s data yet.</strong> Scout reads Azure (Resource Graph and ARM) and one Microsoft Entra policy. It does not call Microsoft Graph for sensitivity labels, SharePoint or Purview, and the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code> holds no Conditional Access, label, sharing, audit or DLP data. The only Graph-backed field, <code>domains.identity.externalIdentitiesPolicy</code>, answers none of these items. So every rule is <code>manual: true</code> with <code>query: null</code>: it is exported as a question by <code>Export-ScoutAssessmentQuestion</code>, answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>), and stays Manual and out of the score until answered. Items marked in the table as needing Entra data are the first that an automated version could take over.</p><p>Sources:</p><ul><li>[BP] <a href="https://learn.microsoft.com/copilot/plan/secure-govern-copilot-foundational-deployment-guidance" target="_blank" rel="noreferrer">Secure and govern Microsoft Copilot: Foundational deployment guidance (remediate oversharing, set up guardrails, meet regulations)</a> -- fetched</li><li>[ARCH] <a href="https://learn.microsoft.com/copilot/plan/architecture-data-protection-auditing" target="_blank" rel="noreferrer">Data protection and auditing for Microsoft Copilot</a> -- fetched</li><li>[ZT] <a href="https://learn.microsoft.com/security/zero-trust/copilots/zero-trust-microsoft-365-copilot" target="_blank" rel="noreferrer">Apply principles of Zero Trust to Microsoft Copilot</a> -- fetched</li><li>[SAM] <a href="https://learn.microsoft.com/sharepoint/advanced-management" target="_blank" rel="noreferrer">What is SharePoint Advanced Management?</a> -- fetched</li><li>[SAMR] <a href="https://learn.microsoft.com/sharepoint/get-ready-copilot-sharepoint-advanced-management" target="_blank" rel="noreferrer">Get ready for Microsoft Copilot and agents with SharePoint Advanced Management</a> -- search excerpt</li><li>[RCD] <a href="https://learn.microsoft.com/sharepoint/restricted-content-discovery" target="_blank" rel="noreferrer">Restrict discovery of SharePoint sites and content (Restricted Content Discovery)</a> -- search excerpt</li><li>[RSS] <a href="https://learn.microsoft.com/sharepoint/restricted-sharepoint-search" target="_blank" rel="noreferrer">Restricted SharePoint Search (retiring)</a> -- search excerpt</li><li>[DAG] <a href="https://learn.microsoft.com/sharepoint/powershell-for-data-access-governance" target="_blank" rel="noreferrer">Manage Data access governance reports by using SharePoint Online PowerShell</a> -- search excerpt</li><li>[DLP] <a href="https://learn.microsoft.com/purview/dlp-microsoft365-copilot-location-learn-about" target="_blank" rel="noreferrer">Use Microsoft Purview Data Loss Prevention to protect interactions with Microsoft 365 Copilot, Copilot Chat, and Cowork</a> -- search excerpt</li><li>[AGT] <a href="https://learn.microsoft.com/purview/deploymentmodels/depmod-sc-agents-deployment" target="_blank" rel="noreferrer">Secure and govern Microsoft 365 Copilot agents (Purview deployment model, steps 1 to 4)</a> -- fetched (overview and step 1)</li><li>[SHADOW] <a href="https://learn.microsoft.com/purview/deploymentmodels/depmod-data-leak-shadow-ai-step3" target="_blank" rel="noreferrer">Step 3: Block sensitive data going to sanctioned AI apps (Purview deployment model)</a> -- search excerpt</li></ul><p>Every item is <strong>manual</strong>: it is exported as a question and scored only when answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>).</p><h2 id="the-enumeration-—-40-items-across-6-groups" tabindex="-1">The enumeration — 40 items across 6 groups <a class="header-anchor" href="#the-enumeration-—-40-items-across-6-groups" aria-label="Permalink to &quot;The enumeration — 40 items across 6 groups&quot;">​</a></h2><h3 id="remediate-oversharing-m365cp-ro-—-11-items" tabindex="-1">Remediate oversharing (M365CP-RO) — 11 items <a class="header-anchor" href="#remediate-oversharing-m365cp-ro-—-11-items" aria-label="Permalink to &quot;Remediate oversharing (M365CP-RO) — 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>M365CP-RO-01</td><td>Oversharing was assessed (Purview data risk assessment or equivalent) before Copilot licences were assigned</td><td>Manual</td><td>BP, ZT, AGT</td></tr><tr><td>M365CP-RO-02</td><td>SharePoint data access governance reports are reviewed for broad exposure</td><td>Manual</td><td>SAM, DAG</td></tr><tr><td>M365CP-RO-03</td><td>High-risk sites are identified from overlapping risk signals and each has a remediation owner</td><td>Manual</td><td>SAMR</td></tr><tr><td>M365CP-RO-04</td><td>Restricted Content Discovery is applied to sites that need review before Copilot can surface them</td><td>Manual</td><td>RCD, SAMR</td></tr><tr><td>M365CP-RO-05</td><td>Restricted SharePoint Search, if used, is temporary and has an exit plan (the feature is retiring)</td><td>Manual</td><td>RSS</td></tr><tr><td>M365CP-RO-06</td><td>Site access reviews or attestations are run by site owners for overshared sites</td><td>Manual</td><td>SAM, SAMR</td></tr><tr><td>M365CP-RO-07</td><td>Every site has owners, and inactive sites are detected and handled</td><td>Manual</td><td>SAM</td></tr><tr><td>M365CP-RO-08</td><td>Restricted access control limits the most sensitive sites and OneDrive locations to named security groups</td><td>Manual</td><td>SAM, ARCH</td></tr><tr><td>M365CP-RO-09</td><td>External sharing defaults and guest settings were reviewed when Copilot was introduced</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-RO-10</td><td>Teams and project sites are protected at baseline, sensitive or highly sensitive level</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-RO-11</td><td>Stale and low-value content is reduced so Copilot does not ground on it</td><td>Manual</td><td>AGT, ZT, SAM</td></tr></tbody></table><h3 id="sensitivity-labels-and-information-protection-m365cp-sl-—-6-items" tabindex="-1">Sensitivity labels and information protection (M365CP-SL) — 6 items <a class="header-anchor" href="#sensitivity-labels-and-information-protection-m365cp-sl-—-6-items" aria-label="Permalink to &quot;Sensitivity labels and information protection (M365CP-SL) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>M365CP-SL-01</td><td>A classification taxonomy exists and sensitivity labels are created and published to users</td><td>Manual</td><td>ZT, ARCH</td></tr><tr><td>M365CP-SL-02</td><td>Sensitivity labels are enabled for Office files in SharePoint and OneDrive</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-SL-03</td><td>Default labelling and mandatory labelling are decided deliberately</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-SL-04</td><td>Container labels protect SharePoint sites and teams that hold sensitive data (Microsoft 365 E5 capability)</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-SL-05</td><td>Automatic labelling finds and labels sensitive content beyond what users label by hand (Microsoft 365 E5 capability)</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-SL-06</td><td>Encryption and usage rights are set with Copilot behaviour in mind (VIEW and EXTRACT)</td><td>Manual</td><td>ARCH</td></tr></tbody></table><h3 id="guardrails-dlp-identity-devices-and-threat-protection-m365cp-gr-—-9-items" tabindex="-1">Guardrails: DLP, identity, devices and threat protection (M365CP-GR) — 9 items <a class="header-anchor" href="#guardrails-dlp-identity-devices-and-threat-protection-m365cp-gr-—-9-items" aria-label="Permalink to &quot;Guardrails: DLP, identity, devices and threat protection (M365CP-GR) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>M365CP-GR-01</td><td>A DLP policy for the Copilot location keeps labelled files and emails out of Copilot processing</td><td>Manual</td><td>DLP</td></tr><tr><td>M365CP-GR-02</td><td>A DLP policy blocks sensitive information types in prompts and is enforced, not left in simulation</td><td>Manual</td><td>DLP</td></tr><tr><td>M365CP-GR-03</td><td>Sensitive prompts are prevented from being sent to external web search</td><td>Manual</td><td>DLP</td></tr><tr><td>M365CP-GR-04</td><td>Insider risk management covers risky AI usage</td><td>Manual</td><td>AGT, SHADOW</td></tr><tr><td>M365CP-GR-05</td><td>Conditional Access requires MFA for all users and administrators and blocks legacy authentication, including Microsoft 365 services</td><td>Manual -- Conditional Access policies are not in collect.json</td><td>ZT</td></tr><tr><td>M365CP-GR-06</td><td>Risk-based access, Privileged Identity Management and access reviews are in place (Entra ID P2 capability)</td><td>Manual -- risk policies, PIM eligibility and access reviews are not in collect.json</td><td>ZT</td></tr><tr><td>M365CP-GR-07</td><td>Devices are enrolled and compliant, and app protection policies cover Copilot-capable apps</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-GR-08</td><td>Threat protection for email, endpoints and identities is deployed and feeds a SIEM</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-GR-09</td><td>Endpoint and browser data protection limits sensitive data going to unsanctioned AI apps</td><td>Manual</td><td>SHADOW</td></tr></tbody></table><h3 id="audit-retention-and-investigation-m365cp-au-—-5-items" tabindex="-1">Audit, retention and investigation (M365CP-AU) — 5 items <a class="header-anchor" href="#audit-retention-and-investigation-m365cp-au-—-5-items" aria-label="Permalink to &quot;Audit, retention and investigation (M365CP-AU) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>M365CP-AU-01</td><td>Microsoft Purview Audit is on and Copilot interactions are being logged</td><td>Manual</td><td>AGT, ARCH</td></tr><tr><td>M365CP-AU-02</td><td>Retention policies cover Copilot interactions</td><td>Manual</td><td>ARCH</td></tr><tr><td>M365CP-AU-03</td><td>eDiscovery and Communication Compliance cover Copilot interaction data</td><td>Manual</td><td>ARCH, ZT</td></tr><tr><td>M365CP-AU-04</td><td>Retention for cloud attachments preserves versions of files Copilot referenced</td><td>Manual</td><td>ARCH</td></tr><tr><td>M365CP-AU-05</td><td>DSPM for AI recommendations are reviewed regularly, especially when users are added</td><td>Manual</td><td>ZT, AGT</td></tr></tbody></table><h3 id="regulations-and-operating-model-m365cp-rg-—-5-items" tabindex="-1">Regulations and operating model (M365CP-RG) — 5 items <a class="header-anchor" href="#regulations-and-operating-model-m365cp-rg-—-5-items" aria-label="Permalink to &quot;Regulations and operating model (M365CP-RG) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>M365CP-RG-01</td><td>Compliance Manager assessments cover the AI regulations that apply</td><td>Manual</td><td>BP, ZT, AGT</td></tr><tr><td>M365CP-RG-02</td><td>Audit and legal requirements for AI interaction records are defined</td><td>Manual</td><td>BP</td></tr><tr><td>M365CP-RG-03</td><td>Protections are rolled out in phases before Copilot licences are assigned to each group of users</td><td>Manual</td><td>ZT</td></tr><tr><td>M365CP-RG-04</td><td>Owners and responsibilities are defined across SharePoint, Purview, identity and security teams</td><td>Manual</td><td>BP</td></tr><tr><td>M365CP-RG-05</td><td>Users and site owners are trained on Copilot and on sharing responsibly</td><td>Manual</td><td>ZT</td></tr></tbody></table><h3 id="agents-m365cp-ag-—-4-items" tabindex="-1">Agents (M365CP-AG) — 4 items <a class="header-anchor" href="#agents-m365cp-ag-—-4-items" aria-label="Permalink to &quot;Agents (M365CP-AG) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>M365CP-AG-01</td><td>The SharePoint and Dataverse content agents use as knowledge is labelled and not overshared</td><td>Manual</td><td>AGT</td></tr><tr><td>M365CP-AG-02</td><td>Sensitive information in Dataverse is discovered with Purview</td><td>Manual</td><td>AGT</td></tr><tr><td>M365CP-AG-03</td><td>Agent creation and agent access to SharePoint and OneDrive are monitored</td><td>Manual</td><td>SAM</td></tr><tr><td>M365CP-AG-04</td><td>Agent interactions are protected, retained and governed like Copilot interactions</td><td>Manual</td><td>AGT</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Remediate oversharing</td><td>11</td><td>0</td><td>11</td></tr><tr><td>Sensitivity labels and information protection</td><td>6</td><td>0</td><td>6</td></tr><tr><td>Guardrails: DLP, identity, devices and threat protection</td><td>9</td><td>0</td><td>9</td></tr><tr><td>Audit, retention and investigation</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Regulations and operating model</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Agents</td><td>4</td><td>0</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>40</strong></td><td><strong>0</strong></td><td><strong>40</strong></td></tr></tbody></table><h2 id="what-an-automated-version-would-need" tabindex="-1">What an automated version would need <a class="header-anchor" href="#what-an-automated-version-would-need" aria-label="Permalink to &quot;What an automated version would need&quot;">​</a></h2><p>Everything below needs a Microsoft Graph app registration with read-only application permissions and tenant admin consent, a new collect section for Microsoft 365 data, and a gate on each rule (an &quot;available&quot; flag, the way <code>governance.budgetsAvailable</code> works) so a tenant that was not read reports Not assessed instead of Pass.</p><table tabindex="0"><thead><tr><th>Items</th><th>What would be read</th><th>Interface and permission</th></tr></thead><tbody><tr><td>M365CP-SL-01, SL-02</td><td>Sensitivity labels defined and published</td><td>Microsoft Graph beta <code>GET /security/informationProtection/sensitivityLabels</code>; application permission <code>InformationProtectionPolicy.Read.All</code> (delegated <code>InformationProtectionPolicy.Read</code>). Beta APIs are not supported in production.</td></tr><tr><td>M365CP-RO-09</td><td>Tenant sharing level, domain restriction mode, guest resharing</td><td>Microsoft Graph v1.0 <code>GET /admin/sharepoint/settings</code> (<code>sharingCapability</code>, <code>sharingDomainRestrictionMode</code>, <code>isResharingByExternalUsersEnabled</code>); <code>SharePointTenantSettings.Read.All</code></td></tr><tr><td>M365CP-RO-02, RO-03, RO-06, RO-07, RO-08, SL-04</td><td>Site-level oversharing: too many users, Everyone except external users, Anyone and organisation-wide links, labelled sites</td><td>SharePoint Online PowerShell (<code>Microsoft.Online.SharePoint.PowerShell</code> 16.0.25409 or later): <code>Start-SPODataAccessGovernanceInsight</code> (needs a SharePoint Advanced Management licence) and the data access governance report cmdlets. No Graph equivalent was found on Learn.</td></tr><tr><td>M365CP-RO-04, RO-05</td><td>Restricted Content Discovery per site; delegation</td><td>SharePoint Online PowerShell: <code>Get-SPOSite</code> property <code>RestrictContentOrgWideSearch</code>, <code>Get-SPOTenant</code> property <code>DelegateRestrictedContentDiscoverabilityManagement</code>, <code>Start-SPORestrictedContentDiscoverabilityReport</code></td></tr><tr><td>M365CP-GR-05, GR-06</td><td>Conditional Access policies (MFA, legacy authentication block, risk policies)</td><td>Microsoft Graph v1.0 <code>GET /identity/conditionalAccess/policies</code>; <code>Policy.Read.All</code>. PIM eligibility and access review definitions are separate Graph APIs that were not researched in this pass.</td></tr><tr><td>M365CP-GR-07</td><td>Device enrolment and compliance</td><td>Microsoft Graph v1.0 <code>GET /deviceManagement/managedDevices</code>; <code>DeviceManagementManagedDevices.Read.All</code></td></tr><tr><td>M365CP-AU-01</td><td>Audit queries for Copilot activity</td><td>Microsoft Graph v1.0 <code>POST /security/auditLog/queries</code> (auditLogQuery); <code>AuditLogsQuery.Read.All</code></td></tr><tr><td>M365CP-AU-05, AG-03</td><td>Copilot interaction history</td><td>Microsoft Graph v1.0 <code>GET /copilot/users/{id}/interactionHistory/getAllEnterpriseInteractions</code>; application permission <code>AiEnterpriseInteraction.Read.All</code>; needs a Copilot licence, and excludes Copilot Studio agent interactions</td></tr><tr><td>M365CP-GR-01 to GR-04, AU-02, AU-03, RG-01</td><td>DLP policies on the Copilot location, retention policies, insider risk and Compliance Manager</td><td>Security &amp; Compliance PowerShell (<code>Connect-IPPSSession</code> from the Exchange Online PowerShell module). Cmdlet names for these policies were not verified in this pass, and no Graph read API for DLP policy was found.</td></tr></tbody></table><p>Items about organisation, training and rollout (M365CP-RG-02 to RG-05, RO-01, RO-10, RO-11) have no API behind them and stay manual in any version.</p>',33)])])}const m=e(d,[["render",i]]);export{p as __pageData,m as default};
